const RELEASE='0.26.0';
const FILES={"IAM_SCOPED_ACCESS_0.26.md":{"gzip":"","sha256":"2ccf69914a62a99e0c6a2b4979cf1368c44227c6f7395a42b527c8e1553bf2aa","size":1758},"IS_Riadenie_odboru_v0.26.0_IAM_SCOPE.sql":{"gzip":"","sha256":"aa9329307b15d324f1d9766a1071c7c4cae4af789c06401db4a942eca1761694","size":24616},"README.md":{"gzip":"","sha256":"489363fc231225370bbbfca2d3d70b1aaf185a5f44bbb8032d441d1abf92d954","size":3338},"README_NASADENIE_0.26.txt":{"gzip":"","sha256":"c387eac8d6cf5b4d55f7480ce3153b172bd9b066dde68ac445a3d9483b5e5607","size":2352},"RELEASE_NOTES.md":{"gzip":"","sha256":"be32a437eb3d336d8d216e48f3d38f5cde286b917b9b365ee8e468f55b074b8c","size":9963},"RELEASE_NOTES_0.26.md":{"gzip":"","sha256":"05a090097f71dfda8ef641ab2267ad60240a0a48a7cafd0469ac3252b4dfa712","size":3679},"package.json":{"gzip":"","sha256":"88464fa932132021fb7a1d72721603f6c5f7ac3d4111b88b496232acba3f6ff7","size":538},"scripts/extract_it_costs_full_year.py":{"gzip":"","sha256":"ab9c4d2565abb8e61fa603eb1cbc668366960a5117be65fba3731673b50bfcbe","size":8906},"src/App.tsx":{"gzip":"","sha256":"598b9f25286f1bd9a6d6ec65f1d10fc8d14a8ed79edd2fc6777a4675e02937c1","size":42635},"src/auth/AuthContext.tsx":{"gzip":"","sha256":"e4cd048fcf2def13514e2a2301028b7181a318eba01a8ca9cbc3fe0e13f09404","size":9404},"src/data/itCostsFullYear.json":{"gzip":"","sha256":"4d8b67f555b2708f9148dbb3f3c725a7101e72eabfaaa7b25a79a5ffa9aebfb8","size":27983},"src/data/seed.json":{"gzip":"","sha256":"a50b1f4b7b960577369a9ab2c0e11fa32026ed1d412aa4bc3564d41360d726ca","size":157729},"src/lib/accessControl.ts":{"gzip":"","sha256":"188fd8b2fadb0f1ac50e472e7bf476d97867dbbcb567abcda58ed8ae34845f92","size":2924},"src/lib/cloud.ts":{"gzip":"","sha256":"0970013fde87b46373837d60acce1ead85dcef5457b80fd8a8c7d00572add751","size":15812},"src/lib/localUsers.ts":{"gzip":"","sha256":"4e8f8e083b8202b55b8791b83e110d97ed76a5eeed44a542977c9edf540147f3","size":8246},"src/lib/storage.ts":{"gzip":"","sha256":"7b5ce5de6b13e399476921ae7e9586cd4b33273297a24793df9d900852c85508","size":30431},"src/styles.css":{"gzip":"","sha256":"db92e12c1bbd33ad3ee9ab7caa127f040518384744ec781b09e9e11c89d415cf","size":123751},"src/types.ts":{"gzip":"","sha256":"f3ff248db8e3fc61ac37994ca2913008e0b49779a9c522b5f21fb9a7dd45bc75","size":11792},"src/views/DepartmentPortal.tsx":{"gzip":"","sha256":"ff89bbc0e7438c70035d876a59f7e06af674f616be1511f5111adb05b89f616c","size":5013},"src/views/FinancialOptimization.tsx":{"gzip":"","sha256":"aeef0bbc0ff8062111d7841d24d093defa6a9373c3514f0fa99efb71c6493ffd","size":16173},"src/views/ItCosts.css":{"gzip":"","sha256":"be862f3ac20f836b28b34a57c6f08752de3ddfd49f719d14bd2e702187d91428","size":13339},"src/views/ItCosts.tsx":{"gzip":"","sha256":"2b83fe5f7ce2ab936505e1e2e5e05bf9d0547e7df88457503134c806ee905dce","size":30880},"src/views/Users.tsx":{"gzip":"","sha256":"7c9cf8b80a58eaadf94112970b6a8e6c73d76a578845e4fe30e5cb61551f34f2","size":42060},"supabase/functions/invite-user/index.ts":{"gzip":"","sha256":"01363529644e207567b839abee25eea2070cd9899de3db3f77284076baa0edbe","size":12403},"supabase/migration_iam_scope_v026.sql":{"gzip":"","sha256":"aa9329307b15d324f1d9766a1071c7c4cae4af789c06401db4a942eca1761694","size":24616}};
const root=process.cwd();
const timestamp=new Date().toISOString().replace(/[:.]/g,'-');
const backup=path.join(root,`backup-before-v0260-${timestamp}`);

function sha256(buf){return crypto.createHash('sha256').update(buf).digest('hex')}
function decode(item){return zlib.gunzipSync(Buffer.from(item.gzip,'base64'))}

console.log(`IS Riadenie odboru – upgrade na v${RELEASE}`);
console.log(`Koreň projektu: ${root}`);

const pkgPath=path.join(root,'package.json');
if(!fs.existsSync(pkgPath)){
  console.error('CHYBA: package.json nebol nájdený. Spustite installer v koreňovom priečinku projektu.');
  process.exit(1);
}
try{
  const current=JSON.parse(fs.readFileSync(pkgPath,'utf8')).version||'';
  console.log(`Aktuálna verzia: ${current||'nezistená'}`);
  if(current && current!=='0.25.0' && current!==RELEASE) console.warn(`UPOZORNENIE: installer bol testovaný pre upgrade z v0.25.0, nájdená je v${current}.`);
}catch{console.warn('UPOZORNENIE: verziu package.json sa nepodarilo načítať.')}

fs.mkdirSync(backup,{recursive:true});
let written=0;
for(const [rel,item] of Object.entries(FILES)){
  const target=path.join(root,...rel.split('/'));
  if(fs.existsSync(target)){
    const backupTarget=path.join(backup,...rel.split('/'));
    fs.mkdirSync(path.dirname(backupTarget),{recursive:true});
    fs.copyFileSync(target,backupTarget);
  }
  const data=decode(item);
  if(sha256(data)!==item.sha256) throw new Error(`Kontrolný súčet payloadu nesedí: ${rel}`);
  fs.mkdirSync(path.dirname(target),{recursive:true});
  fs.writeFileSync(target,data);
  if(sha256(fs.readFileSync(target))!==item.sha256) throw new Error(`Overenie zápisu zlyhalo: ${rel}`);
  written++;
  console.log(`  OK  ${rel}`);
}

for(const cache of ['node_modules/.vite','dist']){
  const p=path.join(root,...cache.split('/'));
  if(fs.existsSync(p)) fs.rmSync(p,{recursive:true,force:true});
}

const pkg=JSON.parse(fs.readFileSync(pkgPath,'utf8'));
if(pkg.version!==RELEASE) throw new Error(`Verifikácia zlyhala: package.json má verziu ${pkg.version}.`);
if(!fs.existsSync(path.join(root,'src','lib','accessControl.ts'))) throw new Error('Verifikácia zlyhala: chýba scoped IAM modul.');
if(!fs.existsSync(path.join(root,'src','data','itCostsFullYear.json'))) throw new Error('Verifikácia zlyhala: chýba full-year IT dataset.');
if(!fs.existsSync(path.join(root,'IS_Riadenie_odboru_v0.26.0_IAM_SCOPE.sql'))) throw new Error('Verifikácia zlyhala: chýba IAM SQL migrácia.');

console.log(`\nVERIFIED: release v${RELEASE} je nainštalovaný do zdrojov (${written} súborov).`);
console.log(`Záloha menených súborov: ${backup}`);
console.log('');
console.log('DÔLEŽITÉ – Supabase:');
console.log('1. V SQL Editore spustite IS_Riadenie_odboru_v0.26.0_IAM_SCOPE.sql.');
console.log('2. Ak používate nové pozvánky, znovu nasaďte Edge Function supabase/functions/invite-user/index.ts.');
console.log('3. Potom spustite npm run build / bežný Vercel deployment.');
